    assertThat(l.get("request_id").asText()).isEqualTo("req-1");
    assertThat(l.has(LoggingInit.LOG_SHIPPED_FIELD)).isFalse();
    assertThat(LoggingInit.currentRequestId()).isNull();
    assertThat(h.canary("c", Map.of())).isFalse();
