  @Test
  void shipsAndCanary() {
    InMemoryLogExporter exporter = new InMemoryLogExporter();
    AtomicInteger closed = new AtomicInteger();
    List<String> lines = new ArrayList<>();
    LoggingHandle h =
        LoggingInit.initLogging(
            InitOptions.builder()
                .service("svc")
                .level("info")
                .env(Map.of("GROW_LOGGING_PROVIDER", SdkInfo.KEY))
                .writer(lines::add)
                .connector(
                    (resource, env, dropped) -> {
                      BatchingLogClient logs =
                          BatchingLogClient.builder(exporter).resource(resource).build();
                      return new LogConnection(
                          logs,
                          () -> {
                            closed.incrementAndGet();
                            logs.close();
                          });
                    })
                .build());
    assertThat(h.shipped()).isTrue();
    h.logger().info("shipped", Map.of("token", "t"));
    assertThat(h.canary("foundation-canary-1", Map.of("foundation.trigger", "health"))).isTrue();
    h.logger().info("tail");
    LogClient sink = h.client();
    sink.send(LogRecord.builder().body("raw").build());
    sink.sendBatch(List.of(LogInput.of("batch")));
    sink.flush();
    sink.flushAsync(Duration.ofSeconds(1)).join();
    assertThat(sink.stats().sent()).isGreaterThanOrEqualTo(0);
    sink.close();
    sink.closeAsync().join();
    h.close();
    h.close();
    assertThat(closed.get()).isEqualTo(1);
    JsonNode l = json(lines.get(0));
    assertThat(l.get(LoggingInit.LOG_SHIPPED_FIELD).asText()).isEqualTo("sdk");
    assertThat(l.get("token").asText()).isEqualTo("[REDACTED]");
    List<String> bodies = exporter.records().stream().map(LogRecord::body).toList();
    assertThat(bodies).contains("shipped", "foundation-canary-1", "raw", "batch");
    assertThat(exporter.records().get(0).resource()).containsEntry("service.name", "svc");
  }

  @Test
  void failedExportsAreReemitted() {
    InMemoryLogExporter exporter = new InMemoryLogExporter();
    for (int i = 0; i < 5; i++) {
      exporter.enqueueOutcome(
          batch -> CompletableFuture.failedFuture(new IllegalStateException("down")));
    }
    List<String> lines = new ArrayList<>();
    LoggingHandle h =
        LoggingInit.initLogging(
            InitOptions.builder()
                .ship(true)
                .env(Map.of("GROW_SERVICE_NAME", "svc", "GROW_ENVIRONMENT", "dev"))
                .writer(lines::add)
                .connector(
                    (resource, env, dropped) -> {
                      BatchingLogClient logs =
                          BatchingLogClient.builder(exporter)
                              .resource(resource)
                              .batchOptions(
                                  BatchOptions.builder()
                                      .maxExportRetries(0)
                                      .onDrop((records, reason) -> dropped.accept(records))
                                      .build())
                              .build();
                      return new LogConnection(logs, logs::close);
                    })
                .build());
    h.logger().info("lost", Map.of("password", "p"));
    h.client()
        .send(
            LogRecord.builder()
                .body("traced")
                .traceId("0102030405060708090a0b0c0d0e0f10")
                .spanId("0102030405060708")
                .build());
    h.flush();
    h.close();
    List<JsonNode> failed =
        lines.stream()
            .map(LoggingInitTest::json)
            .filter(n -> "sdk_failed".equals(n.path(LoggingInit.LOG_SHIPPED_FIELD).asText()))
            .toList();
    assertThat(failed).isNotEmpty();
    assertThat(failed.get(0).get("msg").asText()).isEqualTo("lost");
    assertThat(failed.get(0).get("password").asText()).isEqualTo("[REDACTED]");
    assertThat(failed.get(0).get("service").asText()).isEqualTo("svc");
    assertThat(failed.get(0).get("environment").asText()).isEqualTo("dev");
  }

