    RequestLoggingFilter filter = new RequestLoggingFilter(h.logger());
    Map<String, Object> req = new HashMap<>(Map.of("getHeader", "abc", "getMethod", "GET"));
    req.put("getRequestURI", "/orders");
    Map<String, Object> res = new HashMap<>(Map.of("getStatus", 404));
    String[] seen = new String[1];
